def unique_paths(m, n):
	cache = {}  
	def dp(x, y):
		if x == 0 or y == 0:
			return 1
		if (x, y) not in cache:
			cache[(x, y)] = dp(x-1, y) + dp(x, y-1)
		return cache[(x, y)]
	return dp(m-1, n-1)

